      pk_rsp--;
      if (off < pk_region_end[pk_rsp & PK_RMASK]) {
        out->outcome = 1;
        out->reason = PK_R_REGION_NOT_EXHAUSTED;
        out->consumed_bits = off;
        return 1;
      }
